CREATE TABLE `service_list_items` (`id` INT NOT NULL AUTO_INCREMENT, `service_id` INT NOT NULL, `section` VARCHAR(40) NOT NULL, `text` VARCHAR(300) NOT NULL, `sort_order` INT NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `service_list_items_service_id_section_sort_order_idx` (`service_id`, `section`, `sort_order`), CONSTRAINT `service_list_items_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;